# Get non-empty, non-comment lines
lines = [line.strip() for line in student_code.split('\n') if line.strip() and not line.strip().startswith('#')]

# Join all lines for multi-line pattern matching
full_code = '\n'.join(lines)

# Task 1: Check imports
if not any('import requests' in line for line in lines):
    raise AssertionError('Task 1: Missing "import requests"')
if not any('from bs4 import BeautifulSoup' in line for line in lines):
    raise AssertionError('Task 1: Missing "from bs4 import BeautifulSoup"')
if not any('import json' in line for line in lines):
    raise AssertionError('Task 1: Missing "import json"')

# Task 3: Check URL, GET request, and raise_for_status
if not any("quotes.toscrape.com" in line for line in lines if 'url' in line):
    raise AssertionError('Task 3: URL should be quotes.toscrape.com')
if not any('response' in line and 'requests.get' in line and 'headers=' in line for line in lines):
    raise AssertionError('Task 3: Should use requests.get() with headers= parameter')
if not any('raise_for_status()' in line for line in lines):
    raise AssertionError('Task 3: Missing response.raise_for_status()')

# Task 4: Check BeautifulSoup
if not any('BeautifulSoup' in line and 'response.text' in line and 'html.parser' in line for line in lines):
    raise AssertionError("Task 4: Should use BeautifulSoup(response.text, 'html.parser')")

# Task 5: Check find_all with class_
if not any("find_all('div'" in line and "class_='quote'" in line or 'find_all("div"' in line and 'class_="quote"' in line for line in lines):
    raise AssertionError("Task 5: Should use soup.find_all('div', class_='quote')")

# Task 7: Check find operations inside loop
if 'for quote in quote_divs:' not in student_code:
    raise AssertionError('Task 7: Missing for loop')
if not any(".find('span'" in line and "class_='text'" in line or '.find("span"' in line and 'class_="text"' in line for line in lines):
    raise AssertionError("Task 7: Should find span with class_='text'")
if not any(".find('small'" in line and "class_='author'" in line or '.find("small"' in line and 'class_="author"' in line for line in lines):
    raise AssertionError("Task 7: Should find small with class_='author'")

# Task 8: Check dictionary keys (flexible - search in full code since dict spans multiple lines)
if "'quote'" not in full_code and '"quote"' not in full_code:
    raise AssertionError("Task 8: Dictionary should have 'quote' key")
if "'author'" not in full_code and '"author"' not in full_code:
    raise AssertionError("Task 8: Dictionary should have 'author' key")
if "'tags'" not in full_code and '"tags"' not in full_code:
    raise AssertionError("Task 8: Dictionary should have 'tags' key")

# Task 9: Check JSON file writing
if 'with open' not in student_code:
    raise AssertionError('Task 9: Missing with open() statement')
if 'json.dump' not in student_code:
    raise AssertionError('Task 9: Missing json.dump() call')
if "'scraped_quotes.json'" not in student_code and '"scraped_quotes.json"' not in student_code:
    raise AssertionError("Task 9: Should save to 'scraped_quotes.json'")

print('TEST_PASSED')
